// Einmaliger Nachtrag 2026-07-28: setzt bei bereits veroeffentlichten WordPress-Posts
// (golietz.de = P7, die-partei.net/goslar = P8b) das angezeigte Datum rueckwirkend
// auf vorlageDatum + 3 Tage, analog zur neuen Standardlogik in P7/P8b selbst.
// Ein Vorgang kann auf beiden Seiten gepostet sein -> bis zu 2 Ausgabe-Items pro Zeile.

function safeStr(v) { return v === null || v === undefined ? '' : String(v).trim(); }
function safeBool(v) {
  if (v === true) return true;
  if (typeof v === 'string') return v.trim().toLowerCase() === 'true';
  return false;
}
function targetDateIso(vorlageDatum) {
  const t = Date.parse(safeStr(vorlageDatum));
  if (!Number.isFinite(t)) return null;
  return new Date(t + 3 * 24 * 60 * 60 * 1000).toISOString();
}

const out = [];
for (const item of items) {
  const j = item.json || {};
  const vorlageDatum = safeStr(j.vorlageDatum);
  if (!vorlageDatum) continue;
  const targetDate = targetDateIso(vorlageDatum);
  if (!targetDate) continue;

  if (safeBool(j.wordpressPosted) && safeStr(j.wordpressPostId)) {
    out.push({ json: { vorgangKey: j.vorgangKey, site: 'golietz', postId: safeStr(j.wordpressPostId), targetDate } });
  }
  if (safeBool(j.wordpressGoslarPosted) && safeStr(j.wordpressGoslarPostId)) {
    out.push({ json: { vorgangKey: j.vorgangKey, site: 'diepartei', postId: safeStr(j.wordpressGoslarPostId), targetDate } });
  }
}
return out;

// WICHTIG: die PATCH-HTTP-Nodes liefern die WordPress-Antwort zurueck (bzw. bei Fehler
// ein error-Objekt) - beides ohne vorgangKey/site/postId/targetDate. Der urspruengliche
// Kontext wird deshalb bewusst ueber die vorgelagerte IF-Node wiederhergestellt, statt
// sich auf $input zu verlassen (gleiche Klasse von Bug wie an mehreren anderen Stellen
// in P4/P1 diese Session - siehe allris_p4_claim_release_gap_2026-07-28).
const resp = $input.item.json;
const orig = $('IF golietz.de?').item.json;
const ok = !resp.error && resp.id;
return { json: {
  vorgangKey: orig.vorgangKey,
  site: orig.site,
  postId: orig.postId,
  targetDate: orig.targetDate,
  ergebnis: ok ? ('OK - WP date_gmt jetzt: ' + resp.date_gmt) : ('FEHLER: ' + (resp.error?.message || resp.message || JSON.stringify(resp).slice(0,200)))
} };
